/* Records the durable claim as the primary anonymous-demo conversion. */
(function () {
  'use strict';
  var key = 'ss_anonymous_demo_v1';
  var saved;
  try { saved = JSON.parse(localStorage.getItem(key) || 'null'); } catch (_e) { return; }
  if (!saved || !saved.token) return;
  var allowed = ['https://studio-uploader-production.up.railway.app','https://anonymous-demo-preview-production.up.railway.app'];
  var api = allowed.indexOf(saved.apiBase) !== -1 ? saved.apiBase : allowed[0];
  try { var previous = JSON.parse(localStorage.getItem('ss_anonymous_demo_claimed_v1') || 'null'); if (previous && previous.handle === saved.handle) return; } catch (_) {}
  fetch(api + '/api/demo/status', {cache:'no-store', headers:{'Authorization':'Bearer ' + saved.token, 'Accept':'application/json'}})
    .then(function (response) { return response.ok ? response.json() : null; })
    .then(function (state) {
      if (!state) return;
      if (state.phase === 'claimed') {
        window.dataLayer = window.dataLayer || [];
        window.dataLayer.push({
          event:'anonymous_demo_claimed',
          storefront_handle:state.storefront_handle || saved.handle || ''
        });
        try {
          localStorage.setItem('ss_anonymous_demo_claimed_v1', JSON.stringify({
            handle:state.storefront_handle || saved.handle || '',
            claimedAt:Date.now()
          }));
          saved.claimedAt = Date.now();
          localStorage.setItem(key, JSON.stringify(saved));
        } catch (_e) {}
      } else if (state.phase === 'expired') {
        try { localStorage.removeItem(key); } catch (_e) {}
      }
    }).catch(function () {});
})();

/* Shows a small same-browser resume card on the public homepage. */
(function () {
  'use strict';
  var cfg = document.querySelector('[data-ss-anonymous-demo-resume]');
  if (!cfg) return;
  var saved;
  try { saved = JSON.parse(localStorage.getItem('ss_anonymous_demo_v1') || 'null'); } catch (_e) { return; }
  if (!saved || !saved.token) return;
  var api = String(cfg.getAttribute('data-api-base') || '').replace(/\/+$/, '');
  fetch(api + '/api/demo/status', {cache:'no-store', headers:{'Authorization':'Bearer ' + saved.token, 'Accept':'application/json'}})
    .then(function (response) { return response.ok ? response.json() : null; })
    .then(function (state) {
      if (!state || ['failed','expired','claimed'].indexOf(state.phase) !== -1) return;
      var actions = document.querySelector('.ss-hero-actions');
      if (!actions || document.querySelector('[data-ss-demo-resume-card]')) return;
      var card = document.createElement('a');
      card.setAttribute('data-ss-demo-resume-card','');
      card.className = 'ss-demo-resume-card';
      card.href = cfg.getAttribute('data-resume-path') || saved.startUrl || '/pages/request-storefront-form?view=start-team-store';
      var title = document.createElement('strong');
      title.textContent = state.phase === 'ready' ? 'Your demo store is ready →' : 'Your demo store is building →';
      var detail = document.createElement('span');
      detail.textContent = state.storefront_name || saved.storeName || 'Continue your store';
      card.appendChild(title); card.appendChild(detail); actions.insertAdjacentElement('afterend', card);
    }).catch(function () {});
})();

/* Anonymous store build: resumable, real progress, no forced redirect. */
(function () {
  'use strict';
  var root = document.querySelector('[data-ss-demo-start]');
  if (!root || root.getAttribute('data-enabled') !== 'true') return;
  var key = 'ss_anonymous_demo_v1';
  var api = String(root.getAttribute('data-api-base') || '').replace(/\/+$/, '');
  var $ = function (s) { return root.querySelector(s); };
  var choice = $('[data-demo-choice]'), formPanel = $('[data-demo-form-panel]'), waitPanel = $('[data-demo-wait]');
  var form = $('[data-demo-form]'), submit = $('[data-demo-submit]');
  var current = null, timer = null, controller = null, generation = 0, checking = false, storageWorks = true;
  var reducedMotion = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  function visible(node, yes) { if (node) node.hidden = !yes; }
  function text(selector, value) { var node = $(selector); if (node && node.textContent !== value) node.textContent = value; }
  function event(name, details) {
    window.dataLayer = window.dataLayer || [];
    window.dataLayer.push(Object.assign({event:name}, details || {}));
  }
  function save(value) {
    current = value;
    try { localStorage.setItem(key, JSON.stringify(value)); } catch (_) { storageWorks = false; }
    text('[data-demo-return-copy]', storageWorks ? 'You can close this page and return here in this browser to continue.' : 'Keep this tab open. Your browser is not allowing us to save your progress between visits.');
  }
  function clear() { current = null; try { localStorage.removeItem(key); } catch (_) {} }
  function stop() { generation++; clearTimeout(timer); if (controller) controller.abort(); controller = null; checking = false; }
  function panel(node) {
    [choice, formPanel, waitPanel].forEach(function (p) { visible(p, p === node); });
    visible(root.querySelector('.ss-demo-start__header'), node !== waitPanel);
    if (node) node.scrollIntoView({behavior:reducedMotion ? 'auto' : 'smooth', block:'start'});
  }
  function error(message) { text('[data-demo-error]', message); visible($('[data-demo-error]'), !!message); }
  function stage(index) {
    root.querySelectorAll('[data-demo-progress] li').forEach(function (node, i) {
      node.className = i < index ? 'is-done' : i === index ? 'is-active' : '';
      if (i === index) node.setAttribute('aria-current', 'step'); else node.removeAttribute('aria-current');
    });
  }
  function safeLink(selector, value, fallback) {
    var node = $(selector); if (!node) return;
    try { var u = new URL(value || fallback, location.origin); node.href = u.origin === location.origin ? u.href : fallback; }
    catch (_) { node.href = fallback; }
  }
  function status(state) {
    var phase = String(state.phase || 'building');
    visible($('[data-demo-ready-actions]'), false);
    visible($('[data-demo-recovery]'), false);
    var spinner = $('[data-demo-spinner]');
    if (spinner) { spinner.hidden = false; spinner.classList.toggle('is-done', phase === 'ready' || phase === 'claimed'); }
    var name = state.storefront_name || current.storeName || 'Your team store';
    text('[data-demo-team-name]', name);
    text('[data-demo-team-initials]', name.split(/\s+/).slice(0,2).map(function (part) { return part.charAt(0); }).join('').toUpperCase());
    var logoNode = $('[data-demo-team-logo]');
    if (logoNode && current.logoThumb && /^data:image\/(png|jpeg|webp);base64,/.test(current.logoThumb)) {
      logoNode.src = current.logoThumb; visible(logoNode, true); visible($('[data-demo-team-initials]'), false);
    }
    var labels = {
      saved:['REQUEST SAVED', 'Your team store is on its way.', 'Your logo and team name are saved. We’re getting your store started.', 1],
      store:['CREATING YOUR STORE', 'Making room for ' + name + '.', 'We’re connecting your logo and setting up your team’s store.', 1],
      products:['YOUR LOGO IS IN. WE’LL TAKE IT FROM HERE.', 'Your team store is taking shape.', 'We’re creating your products and previews. Keep exploring below while we finish.', 2],
      finishing:['CHECKING YOUR STORE', 'A few finishing touches.', 'We’re checking your preview before you step inside.', 2]
    };
    if (phase === 'ready' || phase === 'claimed') {
      stage(4);
      text('[data-demo-phase-label]', phase === 'ready' ? 'READY WHEN YOU ARE' : 'YOUR STORE IS ACTIVATED');
      text('[data-demo-status-title]', name + (phase === 'ready' ? ' is ready to explore.' : ' is yours.'));
      text('[data-demo-status-copy]', phase === 'ready' ? 'Explore your gear and try the design tools. Activate your free store whenever you’re ready to keep it.' : 'Your products and saved changes are connected to your account.');
      text('[data-demo-timing]', phase === 'ready' ? 'Purchasing, sharing and inviting members unlock after activation.' : 'You can manage your store from your dashboard.');
      var waitingRoom = '/pages/request-storefront-form?view=start-team-store';
      safeLink('[data-open-preview]', state.preview_url, waitingRoom);
      safeLink('[data-open-admin]', state.admin_url, waitingRoom);
      safeLink('[data-claim-store]', state.claim_url, waitingRoom);
      visible($('[data-demo-ready-actions]'), true);
      if (phase === 'claimed') {
        text('[data-open-admin]', 'Open my dashboard'); $('[data-open-admin]').href = root.getAttribute('data-dashboard-url') || '/pages/portal';
        visible($('[data-claim-store]'), false); visible($('[data-demo-expiry]'), false);
        clear(); history.replaceState(null, '', location.pathname + location.search); return;
      }
      var expires = new Date(state.delete_due_at || state.expires_at || '');
      if (!isNaN(expires.getTime())) {
        text('[data-demo-expiry]', 'Activate to keep this store. Unclaimed previews are scheduled for removal ' + expires.toLocaleString('en-US', {month:'short',day:'numeric',hour:'numeric',minute:'2-digit',timeZone:'America/Los_Angeles',timeZoneName:'short'}) + '.');
        visible($('[data-demo-expiry]'), true);
      }
      if (!current.readyReported) { current.readyReported = true; save(current); event('anonymous_demo_ready', {storefront_handle:state.storefront_handle}); }
      return;
    }
    if (phase === 'expired' || phase === 'failed') {
      if (spinner) spinner.hidden = true;
      text('[data-demo-phase-label]', phase === 'expired' ? 'PREVIEW EXPIRED' : 'YOUR BUILD NEEDS A HAND');
      text('[data-demo-status-title]', phase === 'expired' ? 'Ready for a fresh start?' : 'This is taking longer than expected.');
      text('[data-demo-status-copy]', phase === 'expired' ? 'This unclaimed preview has expired. You can create a new store below.' : 'Your request is saved. Check again or contact us for help with your store.');
      text('[data-demo-timing]', 'No payment was taken.');
      visible($('[data-demo-recovery]'), phase === 'failed');
      if (phase === 'expired') clear();
      return;
    }
    var entry = labels[state.build_stage] || labels.store;
    text('[data-demo-phase-label]', entry[0]); text('[data-demo-status-title]', entry[1]); text('[data-demo-status-copy]', entry[2]); stage(entry[3]);
    if (current.createdAt && Date.now() - current.createdAt > 12 * 60 * 1000) {
      text('[data-demo-timing]', 'Still working on your gear. You can leave this tab and return here in this browser.');
    }
    timer = setTimeout(poll, document.hidden ? 20000 : 5000);
  }
  async function poll() {
    if (!current || !current.token || checking) return;
    clearTimeout(timer); checking = true;
    var mine = generation; var token = current.token;
    controller = new AbortController();
    var timeout = setTimeout(function () { if (mine === generation && controller) controller.abort(); }, 15000);
    try {
      var response = await fetch(api + '/api/demo/status', {cache:'no-store', headers:{Authorization:'Bearer ' + token, Accept:'application/json'}, signal:controller.signal});
      var data = await response.json().catch(function () { return {}; });
      if (mine !== generation) return;
      if (response.status === 401 || response.status === 404 || response.status === 410) { status({phase:'expired'}); return; }
      if (!response.ok) throw new Error('Status unavailable');
      current.handle = data.storefront_handle || current.handle; current.storeName = data.storefront_name || current.storeName; save(current); status(data);
    } catch (_) {
      if (mine !== generation) return;
      text('[data-demo-status-copy]', 'The connection paused. Your build can continue while we reconnect.');
      visible($('[data-demo-recovery]'), true); timer = setTimeout(poll, 8000);
    } finally { clearTimeout(timeout); if (mine === generation) { checking = false; controller = null; } }
  }
  function thumbnail(file) {
    return new Promise(function (resolve) {
      var url = URL.createObjectURL(file), img = new Image();
      img.onload = function () {
        try {
          var canvas = document.createElement('canvas'); canvas.width = 128; canvas.height = 128;
          var scale = Math.min(128 / img.width, 128 / img.height), w = img.width * scale, h = img.height * scale;
          canvas.getContext('2d').drawImage(img, (128-w)/2, (128-h)/2, w, h);
          resolve(canvas.toDataURL('image/png'));
        } catch (_) { resolve(''); }
        URL.revokeObjectURL(url);
      };
      img.onerror = function () { URL.revokeObjectURL(url); resolve(''); };
      img.src = url;
    });
  }
  form.addEventListener('submit', async function (e) {
    e.preventDefault(); error(''); if (!form.reportValidity() || submit.disabled) return;
    var logo = form.elements.storefront_logo_file.files[0];
    if (!logo || logo.size > 12 * 1024 * 1024) { error('Please choose a PNG, JPG or WebP smaller than 12 MB.'); return; }
    submit.disabled = true; submit.textContent = 'Saving your logo…';
    try {
      var logoThumb = await thumbnail(logo);
      var response = await fetch(api + '/api/demo/storefront-request', {method:'POST', body:new FormData(form)});
      var data = await response.json().catch(function () { return {}; });
      if (!response.ok || !data.resume_token) throw new Error(data.error || 'Unable to save your request. Please try again.');
      stop(); save({token:data.resume_token,handle:data.storefront_handle,storeName:form.elements.storefront_name.value,createdAt:Date.now(),readyReported:false,logoThumb:logoThumb,apiBase:api,startUrl:location.pathname+location.search});
      history.replaceState(null, '', location.pathname + location.search); panel(waitPanel); status({phase:'queued',build_stage:'saved'}); poll();
      event('anonymous_demo_started', {storefront_handle:data.storefront_handle});
    } catch (err) { error(err.message); } finally { submit.disabled = false; submit.textContent = 'Build my free store →'; }
  });
  root.querySelectorAll('[data-open-demo-form]').forEach(function (button) { button.addEventListener('click', function () { panel(formPanel); }); });
  $('[data-back-to-choice]').addEventListener('click', function () { panel(choice); });
  $('[data-demo-retry]').addEventListener('click', function () { stop(); poll(); });
  $('[data-demo-start-over]').addEventListener('click', function () {
    if (current && !window.confirm('Start a different store? Your current unclaimed preview will still expire on schedule.')) return;
    stop(); clear(); window.location.assign(root.getAttribute('data-permanent-url') || '/pages/request-storefront-form');
  });
  $('[data-demo-logo]').addEventListener('change', function (e) { text('[data-demo-file-copy]', e.target.files[0] ? e.target.files[0].name : 'PNG, JPG, or WebP · maximum 12 MB'); });
  document.addEventListener('visibilitychange', function () { if (!document.hidden && current) poll(); });
  window.addEventListener('pagehide', stop);
  window.addEventListener('pageshow', function (e) { if (e.persisted && current) poll(); });
  var saved = null; try { saved = JSON.parse(localStorage.getItem(key) || 'null'); } catch (_) {}
  var oldToken = new URLSearchParams(location.hash.slice(1)).get('resume');
  if (oldToken) { saved = {token:oldToken}; history.replaceState(null, '', location.pathname + location.search); }
  if (saved && saved.token) { save(saved); panel(waitPanel); poll(); }
  else window.location.replace(root.getAttribute('data-permanent-url') || '/pages/request-storefront-form');
})();

/* Stella & Sage — unclaimed prospect admin preview. */
(function () {
  'use strict';

  var cfg = window.SSAP || {};
  if (!cfg.isProspectDemo) return;

  var handle = String(cfg.shopHandle || cfg.collectionHandle || '').trim().toLowerCase();
  var root = document.querySelector('.ap-wrap--prospect-demo');
  var claimUrl = cfg.joinLink || ('/pages/join-store?shop=' + encodeURIComponent(handle));
  var apiBase = '/apps/ss/relay/prospect/' + encodeURIComponent(handle);
  var buildWatchActive = false;
  var demo = window.SSProspectDemo = {
    ready: false,
    enabled: false,
    handle: handle,
    token: '',
    sessionId: '',
    state: null,
    claimUrl: claimUrl,
    record: record,
    refresh: bootstrap
  };

  function escapeHtml(value) {
    return String(value == null ? '' : value)
      .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
      .replace(/"/g, '&quot;').replace(/'/g, '&#39;');
  }

  function claimLink(label, className) {
    return '<a href="' + escapeHtml(claimUrl) + '" class="' + (className || 'ap-demo-claim') +
      '" data-prospect-claim>' + escapeHtml(label || 'Claim Your Store') + '</a>';
  }

  // No claim button here on purpose. A prospect can meet four of these in one
  // sitting, and a fifth pitch on each one reads as nagging rather than as an
  // offer. The bar at the bottom of the preview makes the offer once.
  function locked(title, copy) {
    return '<div class="ap-demo-lock" role="status">' +
      '<div class="ap-demo-lock__icon" aria-hidden="true">&#128274;</div>' +
      '<h3>' + escapeHtml(title) + '</h3><p>' + escapeHtml(copy) + '</p></div>';
  }

  // One offer, always reachable, never repeated. It stays put while the
  // prospect moves between tabs, so no individual panel has to carry it.
  function installClaimBar() {
    if (document.getElementById('apDemoClaimBar')) return;
    var bar = document.createElement('div');
    bar.id = 'apDemoClaimBar';
    bar.className = 'ap-demo-bar';
    bar.innerHTML = '<p>You\'re previewing this store. Nothing here is live to your members yet.</p>' +
      claimLink('Claim this store', 'ap-demo-claim');
    document.body.appendChild(bar);
    document.body.classList.add('ap-demo-has-bar');
    bindClaimEvents();
  }

  function lockPanel(tabId, panelId, title, copy) {
    var tab = document.getElementById(tabId);
    var panel = document.getElementById(panelId);
    if (tab) {
      tab.classList.add('ap-demo-tab--locked');
      tab.setAttribute('data-prospect-locked', '1');
      tab.setAttribute('aria-label', title + ' — available after claim');
      var label = tab.querySelector('.ap-tab-label');
      if (label && label.textContent.indexOf('🔒') === -1) label.textContent += ' 🔒';
    }
    if (panel) panel.innerHTML = locked(title, copy);
  }

  function prepareShell() {
    if (root) root.classList.add('ap-prospect-demo--loading');

    // Each says what is behind it and stops. The reason they are locked is on
    // the bar, once, instead of on all four of these.
    lockPanel('apTabBtnProducts', 'apPanelProducts', 'Existing products',
      'Editing, hiding and deleting products are part of the full admin.');
    lockPanel('apTabBtnMembers', 'apPanelMembers', 'Members',
      'Inviting members and adding administrators are part of the full admin.');
    lockPanel('apTabBtnDanger', 'apPanelDanger', 'Store controls',
      'Sleep, deletion and ownership belong to a verified store administrator.');

    var settings = document.getElementById('apPanelSettings');
    if (settings) {
      Array.prototype.slice.call(settings.children).forEach(function (child) {
        if (!child.matches('[data-sfs-root]')) child.remove();
      });
      var appearance = settings.querySelector('[data-sfs-root]');
      var intro = document.createElement('div');
      intro.className = 'ap-demo-settings-intro';
      intro.innerHTML = '<span>Store Customizer</span><h2>Make this storefront yours</h2>' +
        '<p>These are the real appearance controls. Change anything you like.</p>';
      settings.insertBefore(intro, settings.firstChild);
      if (!appearance) {
        var wait = document.createElement('div');
        wait.className = 'ap-demo-appearance-wait';
        wait.textContent = 'Loading the Store Customizer…';
        settings.appendChild(wait);
      }
      settings.insertAdjacentHTML('beforeend', locked('Store identity and fundraising',
        'Renaming, artwork and fundraising are part of the full admin.'));
    }

    ['apBtnShareStore', 'apFrZone'].forEach(function (id) {
      var node = document.getElementById(id);
      if (node) node.style.display = 'none';
    });
    document.querySelectorAll('.ap-hero-actions a').forEach(function (link) {
      if ((link.getAttribute('href') || '').indexOf('/collections/') !== 0) link.style.display = 'none';
    });

    activateTab('apTabBtnAddProducts', 'apPanelAddProducts');
    var addPanel = document.getElementById('apPanelAddProducts');
    if (addPanel) addPanel.classList.add('ap-demo-products--waiting');
  }

  function activateTab(tabId, panelId) {
    document.querySelectorAll('.ap-main-tab-btn').forEach(function (tab) {
      var active = tab.id === tabId;
      tab.classList.toggle('active', active);
      tab.setAttribute('aria-selected', active ? 'true' : 'false');
    });
    document.querySelectorAll('.ap-main-panel').forEach(function (panel) {
      panel.classList.toggle('active', panel.id === panelId);
    });
  }

  function showUnavailable(message) {
    var panel = document.getElementById('apPanelAddProducts');
    if (!panel) return;
    panel.classList.remove('ap-demo-products--waiting');
    panel.innerHTML = locked('The admin preview is unavailable', message || 'Claim this store to continue.');
  }

  function showProductState(state) {
    var panel = document.getElementById('apPanelAddProducts');
    if (!panel) return;
    panel.classList.remove('ap-demo-products--waiting');
    var status = String(state.last_product_status || state.product_status || 'available');
    var existing = panel.querySelector('[data-demo-product-state]');
    if (status === 'available') {
      if (existing) existing.remove();
      return;
    }

    var productUrl = state.product_handle
      ? '/products/' + encodeURIComponent(state.product_handle) + '?preview=1&demo_product=1'
      : '/collections/' + encodeURIComponent(handle) + '?preview=1';
    var banner = existing || document.createElement('div');
    banner.setAttribute('data-demo-product-state', '');
    banner.className = 'ap-demo-complete';
    // The banner reports what happened. The offer to claim lives on the bar,
    // which is already on screen, so repeating it here was the same pitch
    // twice in one viewport.
    if (status === 'completed') {
      if (state.demo_source === 'anonymous_demo' && !window.__ssAnonymousDemoProductReported) {
        window.__ssAnonymousDemoProductReported = true;
        window.dataLayer = window.dataLayer || [];
        window.dataLayer.push({
          event: 'anonymous_demo_product_created',
          storefront_handle: handle,
          product_handle: state.product_handle || ''
        });
      }
      banner.innerHTML = '<span class="ap-demo-complete__check">&#10003;</span>' +
        '<div><h2>Your product is live</h2><p>Keep opening the builders to try artwork, colors and placement.</p></div>' +
        '<div class="ap-demo-complete__actions"><a class="ap-demo-live" href="' + escapeHtml(productUrl) + '">View live product</a></div>';
    } else {
      banner.innerHTML = '<span class="ap-demo-complete__check ap-demo-complete__check--working">&#8230;</span>' +
        '<div><h2>Your product is building</h2><p>This takes a few minutes. You can keep exploring the other builders while it finishes.</p></div>' +
        '<div class="ap-demo-complete__actions"><button type="button" class="ap-demo-live" data-demo-refresh>Refresh status</button></div>';
    }
    if (!existing) panel.insertBefore(banner, panel.firstChild);
    if (status !== 'completed') {
      var refresh = banner.querySelector('[data-demo-refresh]');
      if (refresh) refresh.addEventListener('click', bootstrap);
    }
    bindClaimEvents();
  }

  function bindClaimEvents() {
    document.querySelectorAll('[data-prospect-claim]').forEach(function (link) {
      if (link.dataset.prospectClaimReady === '1') return;
      link.dataset.prospectClaimReady = '1';
      link.addEventListener('click', function () { record('authentication_started'); });
    });
  }

  function record(eventName, details) {
    if (!demo.token || !eventName) return Promise.resolve(false);
    return fetch(apiBase + '/event', {
      method: 'POST',
      headers: {'Content-Type': 'application/json'},
      body: JSON.stringify({demo_token: demo.token, event: eventName, details: details || {}}),
      keepalive: eventName === 'authentication_started'
    }).then(function (response) { return response.ok; }).catch(function () { return false; });
  }

  function bootstrap() {
    return fetch(apiBase + '/state', {cache: 'no-store'})
      .then(function (response) {
        return response.json().catch(function () { return {}; }).then(function (body) {
          if (!response.ok) throw new Error(body.error || ('HTTP ' + response.status));
          return body;
        });
      })
      .then(function (state) {
        demo.ready = true;
        demo.enabled = state.enabled === true;
        demo.state = state;
        demo.token = String(state.demo_token || '');
        demo.sessionId = String(state.session_id || '');
        if (!demo.enabled || !demo.token) {
          showUnavailable('This store has already been claimed or its preview has expired.');
          return;
        }
        if (root) root.classList.remove('ap-prospect-demo--loading');
        showProductState(state);
        bindClaimEvents();
        record('admin_demo_opened');
        record('add_product_opened');
        document.dispatchEvent(new CustomEvent('ss:prospect-demo-ready', {detail: state}));
      })
      .catch(function (error) {
        demo.ready = true;
        showUnavailable(error.message || 'The preview could not be loaded.');
      });
  }

  function watchDemoBuild() {
    if (buildWatchActive) return;
    buildWatchActive = true;
    activateTab('apTabBtnAddProducts', 'apPanelAddProducts');
    showProductState({product_status: 'reserved'});
    var startedAt = Date.now();
    var timer = window.setInterval(function () {
      if (Date.now() - startedAt > 10 * 60 * 1000) {
        window.clearInterval(timer);
        buildWatchActive = false;
        return;
      }
      fetch(apiBase + '/state', {cache: 'no-store'})
        .then(function (response) { return response.ok ? response.json() : null; })
        .then(function (state) {
          if (!state) return;
          if (state.demo_token) demo.token = String(state.demo_token);
          demo.state = state;
          showProductState(state);
          if ((state.last_product_status || state.product_status) === 'completed') {
            window.clearInterval(timer);
            buildWatchActive = false;
            var destination = state.product_handle
              ? '/products/' + encodeURIComponent(state.product_handle) + '?preview=1&demo_product=1'
              : '/collections/' + encodeURIComponent(handle) + '?preview=1&demo_product=1';
            window.setTimeout(function () { window.location.href = destination; }, 900);
          } else if (state.product_status === 'available') {
            window.clearInterval(timer);
            buildWatchActive = false;
            if (state.product_status === 'available') {
              showDemoMessage('The product build did not finish. Your one demo build is available to try again.');
            }
          }
        })
        .catch(function () {});
    }, 5000);
  }

